UPDATE biz_stock 
SET quantity = quantity + #{quantity}, update_time = NOW()
WHERE goods_id = #{goodsId} AND warehouse_id = #{warehouseId}

UPDATE biz_stock 
SET quantity = quantity - #{quantity}, update_time = NOW()
WHERE goods_id = #{goodsId} AND warehouse_id = #{warehouseId} AND quantity >= #{quantity}
